		var rightnow = new GlideDate();
		var inputDate = new GlideDateTime();
		var testdate = new GlideDate();
		testdate.setValue(inputDate.getDate);
		var localcompardate = GlideDate.subtract(testdate,rightnow);
		// If the testdate is the same as rightnow, return true, else return false
		if (localcompardate == 0) {
		return true;
		}
		else {
		return false;
		}
	},*/
    type: 'NeedItUtils'
};
